-- P2: exactly one owner; no finance-table ownership changes.
CREATE TABLE app_owner_state (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  webauthn_user_id bytea NOT NULL CHECK (octet_length(webauthn_user_id) = 32),
  initialized_at timestamptz
);
-- Random user handle is generated by the application, under an advisory lock.
CREATE FUNCTION protect_owner_state() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' OR NEW.webauthn_user_id <> OLD.webauthn_user_id
     OR (OLD.initialized_at IS NOT NULL AND NEW.initialized_at IS DISTINCT FROM OLD.initialized_at) THEN
    RAISE EXCEPTION 'Owner initialization is permanent';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER owner_state_immutable BEFORE UPDATE OR DELETE ON app_owner_state
  FOR EACH ROW EXECUTE FUNCTION protect_owner_state();

CREATE TABLE webauthn_credentials (
  id text PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 2048),
  public_key bytea NOT NULL CHECK (octet_length(public_key) > 0),
  sign_counter bigint NOT NULL CHECK (sign_counter BETWEEN 0 AND 9007199254740991),
  transports text[] NOT NULL DEFAULT '{}',
  device_type text NOT NULL CHECK (device_type IN ('singleDevice', 'multiDevice')),
  backed_up boolean NOT NULL,
  label text NOT NULL CHECK (length(btrim(label)) BETWEEN 1 AND 80),
  created_at timestamptz NOT NULL DEFAULT now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);
CREATE TABLE owner_sessions (
  token_hash text PRIMARY KEY CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  credential_id text NOT NULL REFERENCES webauthn_credentials(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  CHECK (expires_at > created_at AND last_seen_at >= created_at)
);
CREATE INDEX owner_sessions_expiry_idx ON owner_sessions(expires_at);
CREATE INDEX owner_sessions_credential_idx ON owner_sessions(credential_id);
CREATE TABLE recovery_codes (
  code_hash text PRIMARY KEY CHECK (code_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL DEFAULT now(),
  used_at timestamptz,
  CHECK (used_at IS NULL OR used_at >= created_at)
);
CREATE TABLE recovery_grants (
  token_hash text PRIMARY KEY CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  purpose text NOT NULL CHECK (purpose IN ('bootstrap', 'recover')),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  CHECK (expires_at > created_at),
  CHECK (used_at IS NULL OR used_at >= created_at)
);
CREATE TABLE auth_challenges (
  binding_hash text PRIMARY KEY CHECK (binding_hash ~ '^[0-9a-f]{64}$'),
  challenge text NOT NULL UNIQUE,
  purpose text NOT NULL CHECK (purpose IN ('bootstrap', 'login', 'register', 'recover')),
  session_hash text REFERENCES owner_sessions(token_hash) ON DELETE CASCADE,
  recovery_hash text REFERENCES recovery_grants(token_hash) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  CHECK (expires_at > created_at),
  CHECK ((purpose = 'register') = (session_hash IS NOT NULL)),
  CHECK ((purpose IN ('bootstrap', 'recover')) = (recovery_hash IS NOT NULL))
);
CREATE INDEX auth_challenges_expiry_idx ON auth_challenges(expires_at);
CREATE TABLE auth_rate_limits (
  bucket text PRIMARY KEY CHECK (bucket IN ('bootstrap', 'login', 'recovery', 'security')),
  window_start timestamptz NOT NULL,
  attempts integer NOT NULL CHECK (attempts > 0)
);
CREATE TABLE security_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  event text NOT NULL CHECK (event IN ('registered', 'authenticated', 'recovered', 'revoked', 'logout', 'recovery_regenerated', 'sessions_revoked')),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX security_events_time_idx ON security_events(created_at);
